"""Rabin-Karp string matching algorithm using rolling hash."""

BASE = 256
MOD = (1 << 61) - 1  # Mersenne prime for fewer collisions


def rabin_karp(text: str, pattern: str) -> list[int]:
    """Return all starting indices where pattern occurs in text."""
    n, m = len(text), len(pattern)
    if m == 0:
        return list(range(n + 1))
    if m > n:
        return []

    # Precompute BASE^(m-1) % MOD
    h = pow(BASE, m - 1, MOD)

    # Initial hash for pattern and first window
    p_hash = 0
    t_hash = 0
    for i in range(m):
        p_hash = (p_hash * BASE + ord(pattern[i])) % MOD
        t_hash = (t_hash * BASE + ord(text[i])) % MOD

    results = []
    for i in range(n - m + 1):
        if t_hash == p_hash:
            if text[i : i + m] == pattern:
                results.append(i)

        if i < n - m:
            t_hash = (t_hash - ord(text[i]) * h) % MOD
            t_hash = (t_hash * BASE + ord(text[i + m])) % MOD

    return results

"""Comprehensive tests for Rabin-Karp string matching."""

import pytest

from rabin_karp import brute_force, rabin_karp


# ── Helpers ────────────────────────────────────────────────────────────

def _check_both(text, pattern, expected):
    """Assert both algorithms agree and match expected result."""
    assert brute_force(text, pattern) == expected
    assert rabin_karp(text, pattern) == expected


# ── Basic matching ─────────────────────────────────────────────────────

class TestBasicMatching:
    def test_single_match(self):
        _check_both("hello world", "world", [6])

    def test_no_match(self):
        _check_both("abcdef", "gh", [])

    def test_multiple_non_overlapping(self):
        _check_both("abcabcabc", "abc", [0, 3, 6])

    def test_multiple_overlapping(self):
        _check_both("aaaaaa", "aa", [0, 1, 2, 3, 4])

    def test_match_at_start(self):
        _check_both("abcdef", "abc", [0])

    def test_match_at_end(self):
        _check_both("abcdef", "def", [3])

    def test_match_entire_text(self):
        _check_both("abcdef", "abcdef", [0])

    def test_pattern_longer_than_text(self):
        _check_both("abc", "abcdef", [])

    def test_pattern_equals_text(self):
        _check_both("abc", "abc", [0])


# ── Empty inputs ───────────────────────────────────────────────────────

class TestEmptyInputs:
    def test_empty_pattern(self):
        result = rabin_karp("abc", "")
        assert result == [0, 1, 2, 3]

    def test_empty_text(self):
        _check_both("", "a", [])

    def test_both_empty(self):
        _check_both("", "", [0])

    def test_empty_pattern_empty_text(self):
        result = rabin_karp("", "")
        assert result == [0]


# ── Single characters ─────────────────────────────────────────────────

class TestSingleChar:
    def test_single_char_match(self):
        _check_both("a", "a", [0])

    def test_single_char_no_match(self):
        _check_both("a", "b", [])

    def test_single_char_in_longer_text(self):
        _check_both("aaa", "a", [0, 1, 2])

    def test_single_char_not_present(self):
        _check_both("bbb", "a", [])


# ── Repeated patterns ─────────────────────────────────────────────────

class TestRepeatedPatterns:
    def test_repeated_pattern(self):
        _check_both("abababab", "abab", [0, 2, 4])

    def test_all_same_char(self):
        _check_both("aaaa", "aa", [0, 1, 2])

    def test_pattern_repeated_exactly(self):
        _check_both("abcabcabc", "abcabc", [0, 3])

    def test_overlapping_complex(self):
        _check_both("aabaaabaaab", "aabaaab", [0, 4])


# ── Special characters ────────────────────────────────────────────────

class TestSpecialCharacters:
    def test_whitespace(self):
        _check_both("hello world hello", "hello", [0, 12])

    def test_newlines(self):
        _check_both("line1\nline2\nline3", "\n", [5, 11])

    def test_tabs(self):
        _check_both("a\tb\tc", "\t", [1, 3])

    def test_punctuation(self):
        _check_both("hello, world!", "world!", [7])

    def test_regex_special_chars(self):
        _check_both("a.b*c+d", ".b*", [1])

    def test_null_like_chars(self):
        _check_both("a\x00b\x00c", "\x00", [1, 3])


# ── Unicode ────────────────────────────────────────────────────────────

class TestUnicode:
    def test_unicode_basic(self):
        _check_both("hello world", "world", [6])

    def test_chinese_chars(self):
        _check_both("你好世界你好", "你好", [0, 4])

    def test_emoji(self):
        _check_both("hello 😀 world 😀", "😀", [6, 14])

    def test_mixed_unicode(self):
        _check_both("café résumé", "é", [3, 10])

    def test_unicode_pattern(self):
        _check_both("αβγδαβγ", "αβγ", [0, 4])


# ── Hash collision resistance ──────────────────────────────────────────

class TestCollisionResistance:
    def test_near_identical_strings(self):
        """Strings that might produce similar hashes but differ."""
        _check_both("abcabc", "abca", [0])
        _check_both("abcabc", "bcab", [1])

    def test_shifted_pattern(self):
        _check_both("abcdefabc", "def", [3])

    def test_similar_prefix(self):
        _check_both("aabbaabb", "aabb", [0, 4])

    def test_close_but_different(self):
        _check_both("abcdef", "abcde", [0])
        _check_both("abcdef", "bcdef", [1])
        _check_both("abcdef", "abcdf", [])


# ── Large inputs ───────────────────────────────────────────────────────

class TestLargeInputs:
    def test_large_text_small_pattern(self):
        text = "a" * 10000 + "b" + "a" * 10000
        _check_both(text, "b", [10000])

    def test_large_repeating(self):
        text = "abc" * 5000
        result = rabin_karp(text, "abc")
        assert len(result) == 5000
        assert result[0] == 0
        assert result[-1] == 14997

    def test_no_match_large(self):
        text = "a" * 50000
        _check_both(text, "b", [])

    def test_match_at_end_large(self):
        text = "a" * 99999 + "b"
        _check_both(text, "b", [99999])

    def test_pattern_at_every_position(self):
        """Pattern of length 1 in uniform text."""
        text = "a" * 1000
        result = rabin_karp(text, "a")
        assert result == list(range(1000))


# ── Boundary cases ─────────────────────────────────────────────────────

class TestBoundary:
    def test_pattern_one_off_text(self):
        _check_both("abcde", "abcdf", [])

    def test_last_char_different(self):
        _check_both("abcdef", "abcde", [0])

    def test_first_char_different(self):
        _check_both("abcdef", "xbcde", [])

    def test_adjacent_matches(self):
        _check_both("aaab", "aa", [0, 1])

    def test_nested_pattern(self):
        _check_both("abcab", "abc", [0])
        _check_both("abcab", "bca", [1])
        _check_both("abcab", "cab", [2])


# ── Consistency with brute force ───────────────────────────────────────

class TestConsistency:
    @pytest.mark.parametrize("text,pattern", [
        ("abcabcabc", "abc"),
        ("aaaaaa", "aa"),
        ("abcdef", "gh"),
        ("abcdef", ""),
        ("", "a"),
        ("", ""),
        ("a", "a"),
        ("abc", "abcd"),
        ("aabaaabaaab", "aabaaab"),
        ("abababab", "abab"),
        ("hello world", "o"),
        ("mississippi", "issi"),
        ("a" * 100 + "b", "aaaab"),
    ])
    def test_agrees_with_brute_force(self, text, pattern):
        assert rabin_karp(text, pattern) == brute_force(text, pattern)
